import unittest

import mylib as m


class T(unittest.TestCase):
    def test_clamp_hidden(self):
        self.assertEqual(m.clamp(10, 0, 10), 10)
        self.assertEqual(m.clamp(0, 0, 0), 0)

    def test_maximum_hidden(self):
        self.assertEqual(m.maximum([-5, -2, -9]), -2)
        self.assertEqual(m.maximum([7]), 7)

    def test_minimum_hidden(self):
        self.assertEqual(m.minimum([-3, -8]), -8)
        self.assertEqual(m.minimum([2]), 2)

    def test_first_n_hidden(self):
        self.assertEqual(m.first_n([1, 2], 5), [1, 2])
        self.assertEqual(m.first_n([1, 2, 3], 0), [])

    def test_count_vowels_hidden(self):
        self.assertEqual(m.count_vowels(''), 0)
        self.assertEqual(m.count_vowels('xyz'), 0)

    def test_count_even_hidden(self):
        self.assertEqual(m.count_even([]), 0)
        self.assertEqual(m.count_even([0, -2, 3]), 2)

    def test_factorial_hidden(self):
        self.assertEqual(m.factorial(0), 1)
        self.assertEqual(m.factorial(6), 720)


if __name__ == '__main__':
    unittest.main()
